‌​‌​​​‌‌​‌​​​​‌‌​‌‌‌‌​‌‌‌​​‌​​‌‌​‌​​‌​‌‌‌‌​‌​​‌‌​​‌​‌​‌‌​​‌​​​​‌​​​​​​‌‌‌​‌‌​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌​​​‌‌​​​​‌​‌‌‌​‌​​​‌‌​‌​​‌​‌‌​‌‌‌‌​‌‌​‌‌‌​​​‌​​​​​​‌‌​​​​‌​‌‌​‌‌‌​​‌‌​​‌​​​​‌​​​​​​‌​​‌‌​‌​‌​‌​‌​‌​‌​‌​​‌‌​‌​‌​‌​​​​‌​​​​​​‌​​​​‌​​‌​​​‌​‌​​‌​​​​​​‌​‌​​‌​​‌​​​‌​‌​‌​​​‌‌​​‌​‌​‌​‌​‌​‌​​‌‌​‌​​​‌​‌​‌​​​‌​​​​‌​​​​​​‌​​‌​​‌​‌​​‌‌​‌​‌​​‌‌​‌​‌​​​‌​‌​‌​​​‌​​​‌​​‌​​‌​‌​​​​​‌​‌​‌​‌​​​‌​​​‌​‌​‌​​‌‌​​​‌​‌‌​​‌​​‌​‌‌‌​﻿‍
 */

class Version
{
    /**
     * Integer schema version of THIS codebase. Bump by 1 whenever you add a
     * migration entry to migrations/registry.php. Today's release is 1.
     */
    public const SCHEMA = 1;

    /** Human-facing version string (shown in the UI). */
    public const APP = '1.0.0';

    /**
     * The version that first introduced version tracking. A database with no
     * `system_version` row predates this feature, so it is treated as this
     * baseline (then migrated forward as needed).
     */
    public const BASELINE = 1;

    private static ?array $registryCache = null;
    private static ?int $cachedDbVersion = null;
    private static bool $reconciledThisRequest = false;

    /** The migration map: [version => ['name','released','summary','features'[],'up'[]]]. */
    public static function registry(): array
    {
        if (self::$registryCache === null) {
            $path = __DIR__ . '/../migrations/registry.php';
            $reg = is_file($path) ? require $path : [];
            self::$registryCache = is_array($reg) ? $reg : [];
        }
        return self::$registryCache;
    }

    public static function ensureTable(PDO $db): void
    {
        $db->exec('CREATE TABLE IF NOT EXISTS system_version (
            id INT PRIMARY KEY,
            version INT NOT NULL,
            app_version VARCHAR(20) NULL,
            updated_at DATETIME NOT NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4');
    }

    /** Current schema version recorded in the database, or null if none. */
    public static function dbVersion(PDO $db): ?int
    {
        if (self::$cachedDbVersion !== null) {
            return self::$cachedDbVersion;
        }
        try {
            // Fast-path: query directly without DDL lock (in 99.99% of requests the table already exists)
            $row = $db->query('SELECT version FROM system_version WHERE id = 1')->fetch();
            if ($row) {
                self::$cachedDbVersion = (int) $row['version'];
                return self::$cachedDbVersion;
            }
        } catch (\Throwable $e) {
            // Table doesn't exist yet on fresh install — fall through to ensureTable
        }

        try {
            self::ensureTable($db);
            $row = $db->query('SELECT version FROM system_version WHERE id = 1')->fetch();
            self::$cachedDbVersion = $row ? (int) $row['version'] : null;
            return self::$cachedDbVersion;
        } catch (\Throwable $e) {
            return null;
        }
    }

    public static function setDbVersion(PDO $db, int $version, ?string $app = null): void
    {
        self::ensureTable($db);
        $stmt = $db->prepare('INSERT INTO system_version (id, version, app_version, updated_at)
            VALUES (1, :v, :a, NOW())
            ON DUPLICATE KEY UPDATE version = VALUES(version), app_version = VALUES(app_version), updated_at = VALUES(updated_at)');
        $stmt->execute(['v' => $version, 'a' => $app ?? self::APP]);
        self::$cachedDbVersion = $version;
    }

    /**
     * Snapshot used by the API + restore logic.
     * @return array{db:int|null, effective:int, code:int, app:string, state:string, pending:int[]}
     */
    public static function status(PDO $db): array
    {
        $code = self::SCHEMA;
        $dbVer = self::dbVersion($db);
        $effective = $dbVer ?? self::BASELINE; // no row => treat as baseline
        if ($effective === $code) {
            $state = 'current';
        } elseif ($effective < $code) {
            $state = 'behind';
        } else {
            $state = 'ahead';
        }
        $pending = [];
        if ($effective < $code) {
            for ($v = $effective + 1; $v <= $code; $v++) {
                $pending[] = $v;
            }
        }
        return [
            'db'        => $dbVer,
            'effective' => $effective,
            'code'      => $code,
            'app'       => self::APP,
            'state'     => $state,
            'pending'   => $pending,
        ];
    }

    /**
     * Replays migrations from (effective+1) up to the code version, bumping the
     * recorded db version after each. Returns the list of versions applied.
     * No-op when the database is already current or ahead.
     */
    public static function migrateUp(PDO $db): array
    {
        $status = self::status($db);
        if ($status['state'] !== 'behind') {
            // Make sure the version row exists even when nothing needs applying.
            if ($status['db'] === null) {
                self::setDbVersion($db, $status['effective']);
            }
            return [];
        }
        $registry = self::registry();
        $applied = [];
        foreach ($status['pending'] as $v) {
            $entry = $registry[$v] ?? null;
            foreach (($entry['up'] ?? []) as $sql) {
