    /**
     * Boot reconciliation, safe to call on every request:
     *   - creates the version table + seeds the baseline for legacy databases,
     *   - auto-applies any pending forward migrations.
     * Does nothing harmful when the database is current or ahead.
     */
    public static function reconcileOnBoot(PDO $db): void
    {
        if (self::$reconciledThisRequest) {
            return;
        }
        self::$reconciledThisRequest = true;

        $dbVer = self::dbVersion($db);
        if ($dbVer === null) {
            // Legacy database from before version tracking — start at baseline.
            self::setDbVersion($db, self::BASELINE);
        }
        $status = self::status($db);
        if ($status['state'] === 'behind') {
            self::migrateUp($db);
        }
    }

    /**
     * Best-effort read of the version embedded in a backup .sql file, WITHOUT
     * importing it — used to warn before restoring a newer-than-us backup.
     * Streams the file and seeks the tail first to avoid loading huge dumps into RAM.
     * Returns null when neither is present (pre-versioning backup → treat as compatible).
     */
    public static function readVersionFromSql(string $path): ?int
    {
        if (!is_file($path)) {
            return null;
        }

        $size = filesize($path);
        if ($size === false || $size === 0) {
            return null;
        }

        // Check if file is a GZIP archive (magic bytes \x1F\x8B or .gz extension)
        $isGzip = false;
        $fpMagic = @fopen($path, 'rb');
        if ($fpMagic) {
            $magic = fread($fpMagic, 2);
            fclose($fpMagic);
            if ($magic === "\x1F\x8B" || preg_match('/\.gz$/i', $path)) {
                $isGzip = true;
            }
        }

        if ($isGzip && function_exists('gzopen')) {
            $gz = @gzopen($path, 'rb');
            if ($gz) {
                $bytesRead = 0;
                $maxScanBytes = 524288; // 512 KB uncompressed scan
                $buffer = '';
                while (!gzeof($gz) && $bytesRead < $maxScanBytes) {
                    $chunk = gzread($gz, 8192);
                    if ($chunk === false || $chunk === '') break;
                    $buffer .= $chunk;
                    $bytesRead += strlen($chunk);

                    if (preg_match('/--\s*POS25_DB_VERSION:\s*(\d+)/i', $buffer, $m)) {
                        gzclose($gz);
                        return (int) $m[1];
                    }

                    if (preg_match('/INSERT\s+INTO\s+(?:`?\w+`?\.)?`?system_version`?[^;]*VALUES\s*\(\s*\d+\s*,\s*(\d+)/i', $buffer, $m)) {
                        gzclose($gz);
                        return (int) $m[1];
                    }
                }
                gzclose($gz);
            }
            return null;
        }

        $fp = @fopen($path, 'rb');
        if (!$fp) {
            return null;
        }

        // 1. Fast Tail Seek: POS dumps append the version marker to the very end of the file.
        $tailSize = (int) min(8192, $size);
        if (fseek($fp, -$tailSize, SEEK_END) === 0) {
            $tailChunk = fread($fp, $tailSize);
            if ($tailChunk !== false && preg_match('/--\s*POS25_DB_VERSION:\s*(\d+)/i', $tailChunk, $m)) {
                fclose($fp);
                return (int) $m[1];
            }
        }

        // 2. Stream Search: Scan the first 256KB of the file for system_version INSERT or header marker.
        rewind($fp);
        $bytesRead = 0;
        $maxHeaderBytes = min(262144, $size); // 256 KB max scan
        $buffer = '';
        while (!feof($fp) && $bytesRead < $maxHeaderBytes) {
            $chunk = fread($fp, 8192);
            if ($chunk === false) break;
            $buffer .= $chunk;
            $bytesRead += strlen($chunk);

            if (preg_match('/--\s*POS25_DB_VERSION:\s*(\d+)/i', $buffer, $m)) {
                fclose($fp);
                return (int) $m[1];
            }

            if (preg_match('/INSERT\s+INTO\s+(?:`?\w+`?\.)?`?system_version`?[^;]*VALUES\s*\(\s*\d+\s*,\s*(\d+)/i', $buffer, $m)) {
                fclose($fp);
                return (int) $m[1];
            }
        }

        fclose($fp);
        return null;
    }

    /** Comment appended to backups we create, so the version is trivially readable. */
    public static function backupMarker(): string
    {
        return "\n-- POS25_DB_VERSION: " . self::SCHEMA . " (app " . self::APP . ")\n";
